// src/components/Features.jsx
import React from "react";
import { Leaf, BarChart, Database, Zap } from "lucide-react";

const features = [
  { icon: <Leaf />, title: "Eco Recommendations", text: "Get AI-based suggestions for sustainable packaging materials." },
  { icon: <BarChart />, title: "Cost & CO₂ Analysis", text: "Compare materials on cost, carbon impact, and durability." },
  { icon: <Database />, title: "Packaging Database", text: "Access verified data on 20+ eco-friendly materials." },
  { icon: <Zap />, title: "Smart Dashboard", text: "Track history, export reports, and monitor your impact." },
];

const Features = () => (
  <section className="py-20 bg-white">
    <h3 className="text-3xl font-bold text-center mb-10 text-green-800">
      Why Choose EcoPackAI?
    </h3>
    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-8 px-10">
      {features.map((f, i) => (
        <div key={i} className="p-6 rounded-2xl shadow-lg bg-green-50 text-center hover:shadow-xl transition-all">
          <div className="text-green-700 flex justify-center mb-4 text-4xl">{f.icon}</div>
          <h4 className="text-lg font-semibold mb-2">{f.title}</h4>
          <p className="text-gray-700">{f.text}</p>
        </div>
      ))}
    </div>
  </section>
);

export default Features;
